function collapseUnfilledAds() {
  document.querySelectorAll('ins.adsbygoogle[data-ad-status="unfilled"]').forEach(ins => {
    ins.style.setProperty('display', 'none', 'important');

    const host = ins.querySelector('div[id^="aswift_"][id$="_host"]');
    if (host) {
      host.style.setProperty('height', '0px', 'important');
      host.style.setProperty('width', '0px', 'important');
      host.style.setProperty('display', 'none', 'important');
    }

    const iframe = ins.querySelector('iframe[id^="aswift_"]');
    if (iframe) {
      iframe.style.setProperty('height', '0px', 'important');
      iframe.style.setProperty('width', '0px', 'important');
      iframe.style.setProperty('display', 'none', 'important');
    }
  });
}

collapseUnfilledAds();

const observer = new MutationObserver(collapseUnfilledAds);
document.querySelectorAll('ins.adsbygoogle').forEach(ins => {
  observer.observe(ins, { attributes: true, attributeFilter: ['data-ad-status'] });
});
